fn remove_element(s: &Vec<i32>, k: usize) -> Vec<i32> {
    // Precondition: k < s.len()
    assert!(k < s.len(), "index out of bounds");

    // Allocate a new Vec with exactly one less slot than `s`
    let mut result = Vec::with_capacity(s.len() - 1);

    // Copy all elements before index `k`
    result.extend_from_slice(&s[..k]);

    // Copy all elements after index `k`
    result.extend_from_slice(&s[k + 1..]);

    result
}

